CREATE INDEX `idx_objects_workspace_page` ON `objects` (`markaz_id`, (CASE WHEN `kind` IN ('jamaat','event','stay','team','duty','assignment') THEN 0 WHEN `kind`='mashwara' AND COALESCE(CASE WHEN json_valid(`data`) THEN json_extract(`data`,'$.visibility') ELSE NULL END,'markaz')<>'private' THEN 1 WHEN `kind`='mashwara' THEN 2 WHEN `kind`='place' THEN 3 ELSE 4 END), `created_at` DESC, `id` DESC);
